'use strict';
import * as WEMath from 'WEMath';
import * as WEVector from 'WEVector';
import * as WEColor from 'WEColor';

// Every global, member and module function lib.sceneScript.d.ts and the docs' reference declare
// outside the object model (SceneScriptObjectTypingsTests walks that).
const missing = [];
function need(label, ok) { if (!ok) missing.push(label); }
function members(label, target, names, type) {
	need(label, target !== undefined && target !== null);
	if (target === undefined || target === null) return;
	for (const name of names) {
		const kind = typeof target[name];
		need(label + '.' + name + ':' + type, type === 'any' ? kind !== 'undefined' : kind === type);
	}
}

// Global scope: the calls WE allows only here, and the ones it forbids here.
const audio = engine.registerAudioBuffers(engine.AUDIO_RESOLUTION_64);
need('registerAudioBuffers(64)', audio && audio.left instanceof Float32Array && audio.average.length === 64);
const asset = engine.registerAsset('models/still.json');
need('registerAsset', asset !== undefined && asset !== null);
function throwsAtGlobalScope(label, body) {
	try { body(); missing.push(label + ' allowed at global scope'); } catch (error) {}
}
throwsAtGlobalScope('setTimeout', function () { engine.setTimeout(function () {}, 10); });
throwsAtGlobalScope('setInterval', function () { engine.setInterval(function () {}, 10); });
throwsAtGlobalScope('localStorage.get', function () { localStorage.get('key'); });

export function init(value) {
	members('engine', engine, ['frametime', 'runtime', 'timeOfDay', 'AUDIO_RESOLUTION_16', 'AUDIO_RESOLUTION_32',
		'AUDIO_RESOLUTION_64'], 'number');
	members('engine', engine, ['screenResolution', 'canvasSize', 'userProperties'], 'object');
	members('engine', engine, ['isRunningInEditor', 'isPortrait', 'isLandscape', 'isDesktopDevice', 'isMobileDevice',
		'isWallpaper', 'isScreensaver', 'registerAudioBuffers', 'registerAsset', 'setTimeout', 'setInterval',
		'openUserShortcut'], 'function');
	need('engine.AUDIO_RESOLUTION_*', engine.AUDIO_RESOLUTION_16 === 16 && engine.AUDIO_RESOLUTION_32 === 32
		&& engine.AUDIO_RESOLUTION_64 === 64);
	need('engine.isWallpaper', engine.isWallpaper() === true && engine.isScreensaver() === false);
	need('engine.isDesktopDevice', engine.isDesktopDevice() === true && engine.isMobileDevice() === false);
	need('engine.isRunningInEditor', engine.isRunningInEditor() === false);
	need('engine.isPortrait', engine.isPortrait() !== engine.isLandscape());
	need('engine.timeOfDay', engine.timeOfDay >= 0 && engine.timeOfDay <= 1);
	need('engine.canvasSize', engine.canvasSize.x === 1920 && engine.canvasSize.y === 1080);
	need('engine.userProperties.tint', typeof engine.userProperties.tint === 'object' && engine.userProperties.tint.x === 1);
	need('engine.userProperties.level', engine.userProperties.level === 3);
	members('input', input, ['cursorWorldPosition', 'cursorScreenPosition'], 'object');
	members('input', input, ['cursorLeftDown'], 'boolean');
	members('localStorage', localStorage, ['LOCATION_GLOBAL', 'LOCATION_SCREEN'], 'string');
	members('localStorage', localStorage, ['set', 'get', 'delete', 'clear'], 'function');
	need('localStorage.LOCATION_*', localStorage.LOCATION_GLOBAL === 'global' && localStorage.LOCATION_SCREEN === 'screen');
	localStorage.set('probe', { n: 2 });
	need('localStorage.get', localStorage.get('probe').n === 2 && localStorage.get('probe', localStorage.LOCATION_GLOBAL) === undefined);
	need('localStorage.delete', localStorage.delete('probe') === true && localStorage.get('probe') === undefined);
	localStorage.clear(localStorage.LOCATION_GLOBAL);
	members('console', console, ['log', 'error'], 'function');
	need('renderContext', typeof renderContext === 'object' && renderContext !== null);
	need('shared', typeof shared === 'object' && shared !== null);
	need('thisObject', thisObject === thisLayer);
	need('thisScene', typeof thisScene === 'object' && typeof thisScene.getLayer === 'function');
	need('createScriptProperties', typeof createScriptProperties === 'function');
	for (const [name, ctor] of [['Vec2', Vec2], ['Vec3', Vec3], ['Vec4', Vec4], ['Mat3', Mat3], ['Mat4', Mat4],
		['IModelData', IModelData]]) {
		need(name, typeof ctor === 'function');
	}
	need('MediaPlaybackEvent', MediaPlaybackEvent.PLAYBACK_STOPPED === 0 && MediaPlaybackEvent.PLAYBACK_PLAYING === 1
		&& MediaPlaybackEvent.PLAYBACK_PAUSED === 2);
	members('WEMath', WEMath, ['smoothStep', 'mix'], 'function');
	members('WEMath', WEMath, ['deg2rad', 'rad2deg'], 'number');
	members('WEVector', WEVector, ['angleVector2', 'vectorAngle2'], 'function');
	members('WEColor', WEColor, ['rgb2hsv', 'hsv2rgb', 'normalizeColor', 'expandColor'], 'function');
	need('WEMath.mix', WEMath.mix(0, 10, 0.5) === 5);
	need('WEColor.expandColor', WEColor.expandColor(new Vec3(1, 0, 0)).x === 255);
	if (missing.length > 0) throw new Error('missing or wrong: ' + missing.join(', '));
	shared.probeOK = 1;
	return value;
}

alpha.script:
'use strict';
// The order the docs give (and WE's binaries confirm, docs/scenescript-plan.md §1.9 P1/P7/P8):
// init first; applyUserProperties with every property, then applyGeneralSettings, once at load
// and before the first update; no resizeScreen at startup; timers before update in a frame;
// cursorDown, cursorUp, then cursorClick on the same object.
const calls = [];
let updates = 0, cursor = 'none', inside = false;
function fail(message) { throw new Error('lifecycle: ' + message + ' (after ' + calls.slice(-6).join(',') + ')'); }
function vec3(v) { return v !== null && typeof v === 'object' && typeof v.x === 'number' && typeof v.y === 'number' && typeof v.z === 'number'; }
function checkCursorEvent(name, event) {
	if (!vec3(event.worldPosition) || !vec3(event.localPosition)) fail(name + ' event lacks positions');
}
export function init(value) {
	if (calls.length > 0) fail('init not first');
	calls.push('init');
	shared.timeoutUpdates = -1;
	shared.intervalFires = 0;
	engine.setTimeout(function () { shared.timeoutUpdates = updates; }, 0);
	engine.setInterval(function () { shared.intervalFires += 1; }, 0);
	return value;
}
export function applyUserProperties(changed) {
	if (calls.indexOf('applyUserProperties') < 0) {
		if (calls[calls.length - 1] !== 'init') fail('initial applyUserProperties not right after init');
		if (!('flag' in changed) || !('level' in changed) || !('tint' in changed)) fail('initial applyUserProperties lacks properties');
		if (!vec3(changed.tint)) fail('colour property not a Vec3');
	}
	calls.push('applyUserProperties');
	shared.userPropertyCalls = (shared.userPropertyCalls || 0) + 1;
}
export function applyGeneralSettings(settings) {
	if (calls.indexOf('applyGeneralSettings') < 0 && calls[calls.length - 1] !== 'applyUserProperties') {
		fail('initial applyGeneralSettings not right after applyUserProperties');
	}
	if (!/^[a-z]{2}-[a-z]{2,3}$/.test(settings.language)) fail('language ' + settings.language);
	calls.push('applyGeneralSettings');
	shared.generalSettingsCalls = (shared.generalSettingsCalls || 0) + 1;
}
export function resizeScreen(size) {
	if (updates === 0) fail('resizeScreen at startup');
}
export function update(value) {
	if (updates === 0 && calls.join(',') !== 'init,applyUserProperties,applyGeneralSettings') fail('load order');
	if (updates === 0 && shared.timeoutUpdates !== 0) fail('a 0 ms timeout did not fire before the first update');
	updates += 1;
	if (shared.intervalFires !== updates) fail('a 0 ms interval fired ' + shared.intervalFires + ' times in ' + updates + ' frames');
	shared.lifecycleUpdates = updates;
	return value;
}
export function cursorEnter(event) { checkCursorEvent('cursorEnter', event); inside = true; shared.cursorEnters = (shared.cursorEnters || 0) + 1; }
export function cursorLeave(event) { checkCursorEvent('cursorLeave', event); inside = false; }
export function cursorMove(event) { checkCursorEvent('cursorMove', event); }
export function cursorDown(event) {
	checkCursorEvent('cursorDown', event);
	if (!inside) fail('cursorDown without cursorEnter');
	cursor = 'down';
}
export function cursorUp(event) {
	checkCursorEvent('cursorUp', event);
	if (cursor !== 'down') fail('cursorUp without cursorDown');
	cursor = 'up';
}
export function cursorClick(event) {
	checkCursorEvent('cursorClick', event);
	if (cursor !== 'up') fail('cursorClick before cursorUp');
	cursor = 'clicked';
	shared.clicks = (shared.clicks || 0) + 1;
}
export function destroy() {}

