'use strict';
// Every media event's payload, as the d.ts declares it.
function fail(message) { throw new Error('media: ' + message); }
function count(name) { shared[name] = (shared[name] || 0) + 1; }
function vec3(v) { return v !== null && typeof v === 'object' && typeof v.x === 'number' && typeof v.y === 'number' && typeof v.z === 'number'; }
export function mediaStatusChanged(event) {
	if (typeof event.enabled !== 'boolean') fail('status enabled');
	count('mediaStatus');
}
export function mediaPlaybackChanged(event) {
	if ([MediaPlaybackEvent.PLAYBACK_STOPPED, MediaPlaybackEvent.PLAYBACK_PLAYING, MediaPlaybackEvent.PLAYBACK_PAUSED]
		.indexOf(event.state) < 0) fail('playback state ' + event.state);
	count('mediaPlayback');
}
export function mediaPropertiesChanged(event) {
	for (const name of ['title', 'artist', 'subTitle', 'albumTitle', 'albumArtist', 'genres', 'contentType']) {
		if (typeof event[name] !== 'string') fail('properties ' + name + ' is ' + typeof event[name]);
	}
	count('mediaProperties');
}
export function mediaThumbnailChanged(event) {
	if (typeof event.hasThumbnail !== 'boolean') fail('thumbnail hasThumbnail');
	for (const name of ['primaryColor', 'secondaryColor', 'tertiaryColor', 'textColor', 'highContrastColor']) {
		if (!vec3(event[name])) fail('thumbnail ' + name);
	}
	count('mediaThumbnail');
}
export function mediaTimelineChanged(event) {
	if (typeof event.position !== 'number' || typeof event.duration !== 'number') fail('timeline');
	count('mediaTimeline');
}

