'use strict';
// destroyLayer removes the layer after every script's update of that frame (the docs), and calls
// the destroy() of the scripts on it once.
let done = false;
export function update(value) {
	if (!done && engine.runtime > 1) {
		done = true;
		shared.updatesAtDestroyLayer = shared.doomedUpdates;
		thisScene.destroyLayer('Doomed');
	}
	return value;
}

'use strict';
export function update(value) {
	shared.doomedUpdates = (shared.doomedUpdates || 0) + 1;
	return value;
}
export function destroy() {
	shared.doomedDestroyCalls = (shared.doomedDestroyCalls || 0) + 1;
	shared.doomedUpdatesAtDestroy = shared.doomedUpdates;
}
